-- ============================================================================
-- Costing module — seed from barramundi_costing_v11.xlsx
--
-- GENERATED by packages/engine/scripts/gen-costing-seed.mjs from the committed
-- fixture packages/engine/fixtures/v11.json. Do not hand-edit: regenerate.
--
-- Values are the workbook's own, and the engine reproduces them to a relative
-- 1e-9 (packages/engine/test/costing-parity.test.ts). Two things here are
-- deliberately NOT the workbook:
--   1. The six by-product SKUs ship as raw_material_basis = absorbed
--      (Decisions §7). The other 28 are full_fish and match v11 exactly.
--   2. Per-bucket FCR is the workbook's PLACEHOLDER (v11 flags it as such at
--      cell A22), and per-bucket yields are seeded from each SKU's flat yield.
--      Both are editable and get real farm data later (Decisions §6).
-- ============================================================================

set search_path = demand_planner, public;

-- ---------------------------------------------------------------------------
-- 1. Size buckets — costing's own copy (Decisions §6)
-- ---------------------------------------------------------------------------
insert into demand_planner.cost_size_buckets (org_id, label, min_g, max_g, median_g, fcr, sort_order)
select o.id, b.label, b.min_g, b.max_g, b.median_g, b.fcr, b.sort_order
from demand_planner.organizations o,
     (values
        ('0-600g', 0, 600, 300, 1.1::numeric, 10),
        ('600-800g', 600, 800, 700, 1.25::numeric, 20),
        ('800-1100g', 800, 1100, 950, 1.35::numeric, 30),
        ('1100-1500g', 1100, 1500, 1300, 1.45::numeric, 40),
        ('1500-1800g', 1500, 1800, 1650, 1.55::numeric, 50),
        ('1800-2200g', 1800, 2200, 2000, 1.65::numeric, 60),
        ('2200-4000g', 2200, 4000, 3100, 1.75::numeric, 70)
     ) as b(label, min_g, max_g, median_g, fcr, sort_order)
where o.slug = 'oceanpick'
on conflict (org_id, label) do nothing;

-- ---------------------------------------------------------------------------
-- 2. Destinations — the port list (rates land on the version, below)
-- ---------------------------------------------------------------------------
insert into demand_planner.cost_destinations (org_id, name, sort_order)
select o.id, d.name, d.sort_order
from demand_planner.organizations o,
     (values
        ('Dubai (UAE)', 10),
        ('Singapore', 20),
        ('Doha (Qatar)', 30),
        ('Male (Maldives)', 40),
        ('Hong Kong', 50),
        ('London (UK)', 60),
        ('Sydney (AU)', 70),
        ('New York (US)', 80),
        ('Melbourne (AU)', 90),
        ('Brisbane (AU)', 100),
        ('Perth (AU)', 110),
        ('Adelaide (AU)', 120),
        ('Los Angeles (US)', 130),
        ('Miami (US)', 140),
        ('Amsterdam (NL)', 150)
     ) as d(name, sort_order)
where o.slug = 'oceanpick'
on conflict (org_id, name) do nothing;

-- ---------------------------------------------------------------------------
-- 3. Assumption version 1 — the workbook as at v11 (Decisions §4)
-- ---------------------------------------------------------------------------
insert into demand_planner.cost_assumption_versions (
  org_id, version_no, label, notes, is_current,
  feed_cost_per_kg, clearing_cost_per_kg, fcr_reference, fx_rate,
  import_tax_pct_domestic, import_tax_pct_export,
  domestic_transport_lkr, domestic_cold_hold_lkr,
  export_freight_to_port_usd, export_cold_chain_usd,
  rack_margin_pct, fob_margin_pct,
  importer_clearing_pct, importer_markup_pct, distributor_markup_pct,
  container_fill_kg, air_lot_kg
)
select
  o.id, 1, 'v11 (imported)', 'Imported from barramundi_costing_v11.xlsx', true,
  1.35, 0.05, 1.5, 340,
  0.35, 0,
  60, 40,
  0.1, 0.1,
  0.4, 0.4,
  0.05, 0.1, 0.15,
  7000, 500
from demand_planner.organizations o
where o.slug = 'oceanpick'
on conflict (org_id, version_no) do nothing;

-- ---------------------------------------------------------------------------
-- 4. ODC components (Decisions §3 / handoff §3.2)
--
-- basis drives size-bucket amortisation: per_fish divides by the median
-- weight, per_kg stays flat. v11 hard-codes this; here it is editable.
-- ---------------------------------------------------------------------------
insert into demand_planner.cost_odc_components (version_id, name, value, currency, basis, sort_order)
select v.id, c.name, c.value, c.currency::demand_planner.cost_currency, c.basis::demand_planner.cost_odc_basis, c.sort_order
from demand_planner.cost_assumption_versions v
join demand_planner.organizations o on o.id = v.org_id
cross join (values
        ('fingerling', 0.25::numeric, 'USD', 'per_fish', 10),
        ('transport - trinco/colombo', 19::numeric, 'LKR', 'per_kg', 20),
        ('ice', 12::numeric, 'LKR', 'per_kg', 30),
        ('vaccine', 23.4::numeric, 'LKR', 'per_fish', 40),
        ('additives', 0::numeric, 'USD', 'per_kg', 50),
        ('royalty', 5::numeric, 'LKR', 'per_kg', 60)
     ) as c(name, value, currency, basis, sort_order)
where o.slug = 'oceanpick' and v.version_no = 1
on conflict (version_id, name) do nothing;

-- ---------------------------------------------------------------------------
-- 5. Destination rates for version 1
--
-- Per shipment, not per kg: the engine divides by container_fill_kg /
-- air_lot_kg so changing the fill weight reprices every port at once.
-- ---------------------------------------------------------------------------
insert into demand_planner.cost_destination_rates (version_id, destination_id, sea_rate_per_20ft, air_rate_per_lot)
select v.id, d.id, r.sea, r.air
from demand_planner.cost_assumption_versions v
join demand_planner.organizations o on o.id = v.org_id
join (values
        ('Dubai (UAE)', 3150::numeric, 1400::numeric),
        ('Singapore', 2800::numeric, 1250::numeric),
        ('Doha (Qatar)', 3500::numeric, 1450::numeric),
        ('Male (Maldives)', 2450::numeric, 900::numeric),
        ('Hong Kong', 3150::numeric, 1300::numeric),
        ('London (UK)', 5950::numeric, 2250::numeric),
        ('Sydney (AU)', 4900::numeric, 1900::numeric),
        ('New York (US)', 7700::numeric, 2750::numeric),
        ('Melbourne (AU)', 5200::numeric, 2000::numeric),
        ('Brisbane (AU)', 4800::numeric, 1900::numeric),
        ('Perth (AU)', 4500::numeric, 1850::numeric),
        ('Adelaide (AU)', 5000::numeric, 1950::numeric),
        ('Los Angeles (US)', 6500::numeric, 2400::numeric),
        ('Miami (US)', 7000::numeric, 2600::numeric),
        ('Amsterdam (NL)', 6200::numeric, 2300::numeric)
     ) as r(name, sea, air) on true
join demand_planner.cost_destinations d on d.org_id = o.id and d.name = r.name
where o.slug = 'oceanpick' and v.version_no = 1
on conflict (version_id, destination_id) do nothing;

