-- ---------------------------------------------------------------------------
-- 7. Per-bucket yields — PLACEHOLDERS (Decisions §6)
--
-- Every bucket starts at the SKU's flat yield, so the table is usable from
-- day one and obviously still needs real data: while every bucket holds the
-- same number, switching buckets on changes only FCR and ODC, never yield.
-- Replace with the farm's yield at each bucket median.
-- ---------------------------------------------------------------------------
insert into demand_planner.cost_sku_bucket_yields (sku_id, bucket_id, yield_pct)
select s.id, b.id, s.base_yield
from demand_planner.cost_skus s
join demand_planner.cost_size_buckets b on b.org_id = s.org_id
on conflict (sku_id, bucket_id) do nothing;

-- ---------------------------------------------------------------------------
-- 8. Sanity check
-- ---------------------------------------------------------------------------
do $$
declare
  n_skus int;
  n_absorbed int;
begin
  select count(*) into n_skus
    from demand_planner.cost_skus s
    join demand_planner.organizations o on o.id = s.org_id
   where o.slug = 'oceanpick';
  select count(*) into n_absorbed
    from demand_planner.cost_skus s
    join demand_planner.organizations o on o.id = s.org_id
   where o.slug = 'oceanpick' and s.raw_material_basis = 'absorbed';
  if n_skus <> 34 then
    raise exception 'expected 34 costing SKUs, found %', n_skus;
  end if;
  if n_absorbed <> 6 then
    raise exception 'expected 6 absorbed by-product SKUs, found %', n_absorbed;
  end if;
end $$;
